/**
 * Visual + navigation enrichment for the Help / Documentation page.
 *
 * Kept separate from the generated helpContent.ts so the documentation copy
 * (generated by scripts/gen-help-i18n.js) and the screenshot / deep-link config
 * can each evolve independently. HelpView merges this map onto HELP_SECTIONS by id.
 *
 * Screenshots: `src` points at a file under /public. The <ScreenshotPreview> lazy-loads
 * it and gracefully falls back to a styled placeholder when the file is absent — so the
 * page works today and you can drop real captures into public/help/ incrementally.
 * Recommended size ~1280×800 (16:10), <300KB each (WebP/PNG).
 *
 * Deep links:
 *  - kind 'view'  → in-app SPA view (home | market | hub | map | subscription | profile …)
 *  - kind 'route' → real Next route (/dashboard/*). `requiresDashboard` hides it from guests.
 *
 * All labels/captions are i18n keys — never hardcode visible text here.
 */

import type { HelpLink, HelpMedia } from './helpContent';

export interface HelpEnrichment {
  media?: HelpMedia[];
  links?: HelpLink[];
}

/** Convention: screenshots live at /public/help/<id>.png (override per item if needed). */
const shot = (id: string): string => `/help/${id}.png`;

/**
 * Feature flag — deep-link buttons whose `labelKey` is listed here are temporarily
 * hidden from the Help page (their definitions below stay intact for easy reuse).
 * To re-enable a button, remove its label key from this set.
 *
 * Currently disabled: "Open Profile" and "Open Subscription".
 */
const DISABLED_HELP_LINK_LABELS = new Set<HelpLink['labelKey']>([
  'helpLinkOpenProfile',
  'helpLinkOpenSubscription',
]);

/**
 * Returns the enrichment for a section with any feature-flagged links filtered out.
 * Use this (not HELP_ENRICHMENTS directly) anywhere links are rendered, so the flag
 * is honoured consistently. Navigation logic/routes are preserved — only UI is gated.
 */
export function getHelpEnrichment(id: string): HelpEnrichment | undefined {
  const raw = HELP_ENRICHMENTS[id];
  if (!raw) return undefined;
  if (!raw.links?.length || DISABLED_HELP_LINK_LABELS.size === 0) return raw;
  const links = raw.links.filter((l) => !DISABLED_HELP_LINK_LABELS.has(l.labelKey));
  return { ...raw, links };
}

